-- ==========================================================
-- Job Portal Project - Massive Multi-Domain Dataset
-- ==========================================================

CREATE TABLE IF NOT EXISTS users (
    id BIGSERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    email VARCHAR(255) NOT NULL UNIQUE,
    password VARCHAR(255) NOT NULL,
    provider VARCHAR(255) NOT NULL DEFAULT 'LOCAL',
    role VARCHAR(255) NOT NULL DEFAULT 'USER',
    skills TEXT DEFAULT '',
    job_title VARCHAR(255) DEFAULT '',
    experience INTEGER DEFAULT 0
);

CREATE TABLE IF NOT EXISTS jobs (
    id BIGSERIAL PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    company VARCHAR(255) NOT NULL,
    location VARCHAR(255) NOT NULL,
    description TEXT,
    source VARCHAR(255) NOT NULL,
    apply_link VARCHAR(2000) NOT NULL,
    posted_time TIMESTAMP WITHOUT TIME ZONE NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_title ON jobs (title);
CREATE INDEX IF NOT EXISTS idx_location ON jobs (location);
CREATE INDEX IF NOT EXISTS idx_source ON jobs (source);
CREATE INDEX IF NOT EXISTS idx_company ON jobs (company);
CREATE INDEX IF NOT EXISTS idx_posted_time ON jobs (posted_time);
CREATE INDEX IF NOT EXISTS idx_title_company_source ON jobs (title, company, source);

CREATE TABLE IF NOT EXISTS applications (
    id BIGSERIAL PRIMARY KEY,
    user_id BIGINT NOT NULL,
    job_id BIGINT NOT NULL,
    status VARCHAR(255) NOT NULL,
    saved_at TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    CONSTRAINT fk_applications_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_applications_job FOREIGN KEY (job_id) REFERENCES jobs(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_applications_user_id ON applications (user_id);
CREATE INDEX IF NOT EXISTS idx_applications_job_id ON applications (job_id);

